const B=[{"id": "christianity", "o": 1, "f": "الأديان الإبراهيمية", "t": "المسيحية · عودة يسوع المسيح", "n": "Jesus / Second Coming", "c": "A", "conf": "عالٍ", "pop": "28.8% من سكان العالم (تصنيف مركز بيو (Pew)، بيانات 2020)", "sum": "المسيحية لا تنتظر مخلّصاً بشرياً جديداً مستقلاً؛ مركز الرجاء الأخروي هو عودة يسوع المسيح نفسه. لذلك أي مقارنة بشخص معاصر يجب أن تبدأ من هذا الشرط الحاسم، لا من التشابه الأخلاقي العام.", "rafi": "غير منطبق", "lux": "تقاطع قيمي", "guard": "تقاطع وظيفي محدود", "url": "research/savior/christianity.html"}, {"id": "islam-sunni", "o": 2, "f": "الأديان الإبراهيمية", "t": "الإسلام السني · المهدي وعودة عيسى", "n": "Mahdi + Return of Jesus", "c": "A", "conf": "متوسط–عالٍ", "pop": "جزء من الإسلام، الذي يمثل 25.6% عالمياً", "sum": "في التراث السني، أحاديث المهدي موجودة في مجموعات حديثية متعددة، بينما عودة عيسى جزء بارز من التصورات الأخروية. مكانة تفاصيل المهدي ودرجة الأحاديث وتفسير العلامات تختلف بين العلماء والمدارس.", "rafi": "غير مثبت", "lux": "تقاطع قيمي جزئي", "guard": "فرضية رمزية فقط", "url": "research/savior/islam-sunni.html"}, {"id": "islam-twelver", "o": 3, "f": "الأديان الإبراهيمية", "t": "الإسلام الاثنا عشري · الإمام المهدي الغائب", "n": "Hidden Imam / al-Mahdi", "c": "A", "conf": "عالٍ", "pop": "فرع رئيسي داخل الإسلام الشيعي", "sum": "الاثنا عشرية لا تنتظر شخصية مجهولة الصفات يمكن إسقاطها على أي معاصر؛ العقيدة تحدد المهدي بالإمام الثاني عشر، محمد بن الحسن العسكري، في الغيبة حتى الظهور.", "rafi": "غير منطبق", "lux": "تقاطع قيمي فقط", "guard": "غير منطبق نبوئياً", "url": "research/savior/islam-twelver.html"}, {"id": "hinduism", "o": 4, "f": "الديانات الهندية", "t": "الهندوسية · كالكي (Kalki)", "n": "Kalki", "c": "A", "conf": "عالٍ", "pop": "14.9% من سكان العالم", "sum": "في التقاليد الفيشنافية، كالكي (Kalki) هو الأفاتار المستقبلي لفيشنو المرتبط بنهاية كالي يوغا (Kali Yuga) واستعادة الدارما (dharma). هذه هوية لاهوتية وكوزمولوجية محددة أكثر من كونها وصفاً لأي مصلح أخلاقي.", "rafi": "غير مثبت / تعارض جوهري", "lux": "تقاطع بنيوي جزئي", "guard": "تقاطع رمزي محدود", "url": "research/savior/hinduism.html"}, {"id": "buddhism", "o": 5, "f": "الديانات الهندية", "t": "البوذية · مايتريا (Maitreya / Metteyya)", "n": "Maitreya", "c": "A", "conf": "عالٍ", "pop": "4.1% من سكان العالم", "sum": "مايتريا (Maitreya) هو بوذا المستقبل في تقاليد بوذية متعددة. الفكرة المركزية ليست «منقذاً سياسياً» بل بوذا سيظهر في زمن لاحق ويعيد تعليم الدارما.", "rafi": "غير مثبت", "lux": "تقاطع معرفي/أخلاقي", "guard": "تقاطع وظيفي ضعيف", "url": "research/savior/buddhism.html"}, {"id": "judaism", "o": 6, "f": "الأديان الإبراهيمية", "t": "اليهودية · المشيح", "n": "Mashiach / Messiah", "c": "A", "conf": "عالٍ", "pop": "أقل من 1% عالمياً، مع تأثير تاريخي كبير", "sum": "المشيح في اليهودية مفهوم متعدد الطبقات، لكنه في الصيغ التقليدية يرتبط بملك/قائد بشري من بيت داود وعصر عدل وسلام وجمع للمنفيين، لا بالإله المتجسد.", "rafi": "غير مثبت", "lux": "تقاطع قيمي", "guard": "تقاطع رمزي محدود", "url": "research/savior/judaism.html"}, {"id": "bahai", "o": 7, "f": "الأديان العالمية الحديثة", "t": "البهائية · الموعود والوحدة الإنسانية", "n": "Bahá’u’lláh / Promised One", "c": "A", "conf": "عالٍ", "pop": "ضمن فئة الديانات الأخرى عالمياً", "sum": "البهائية حالة مختلفة: العقيدة لا تنتظر الآن موعود القرن التاسع عشر بوصفه مجهولاً، بل تعتبر أن بهاءالله هو الموعود الذي حقق وعود دور ديني جديد، مع تركيز قوي على وحدة البشرية والسلام العالمي.", "rafi": "غير منطبق داخل العقيدة", "lux": "تقاطع بنيوي قوي", "guard": "تقاطع تنظيمي/أخلاقي", "url": "research/savior/bahai.html"}, {"id": "zoroastrianism", "o": 8, "f": "الديانات الإيرانية", "t": "الزرادشتية · ساوشيانت (Saošyant)", "n": "Saošyant", "c": "A", "conf": "عالٍ", "pop": "أقلية صغيرة عالمياً، ذات أثر تاريخي كبير", "sum": "ساوشيانت (Saošyant) يبدأ لغوياً/نصياً بمعنى قريب من النافع أو المعين، ثم يتطور في الأخرويات الزرادشتية إلى المخلّص الأخير المرتبط بالتجديد النهائي. هذا يجعل الفصل بين الاستخدام المبكر والتطور المتأخر ضرورياً.", "rafi": "غير مثبت", "lux": "تقاطع بنيوي متوسط", "guard": "تقاطع وظيفي متوسط", "url": "research/savior/zoroastrianism.html"}, {"id": "javanese", "o": 9, "f": "التقاليد الجاوية", "t": "الجاوية · راتو عادل (Ratu Adil)", "n": "Ratu Adil / Just King", "c": "B", "conf": "متوسط", "pop": "تقليد ثقافي/ديني إقليمي داخل إندونيسيا", "sum": "راتو عادل (Ratu Adil)، «الملك العادل»، نموذج مهدوي جاوي ظهر في سياقات دينية وسياسية متنوعة. مرونته التاريخية تجعله مهماً للمقارنة، لكنها أيضاً تجعل تعيين شخص معاصر شديد الضعف ما لم توجد معايير نصية مبكرة محددة.", "rafi": "غير قابل للتعيين حالياً", "lux": "تقاطع موضوعي", "guard": "تقاطع رمزي", "url": "research/savior/javanese.html"}, {"id": "caodai", "o": 10, "f": "شرق آسيا والديانات التوفيقية", "t": "كاو داي (Cao Dai) · العفو الثالث ووحدة الأديان", "n": "Third Amnesty / Universal salvation", "c": "B", "conf": "عالٍ", "pop": "ديانة فيتنامية حديثة", "sum": "كاو داي (Cao Dai) أقل اعتماداً على «مخلّص واحد» وأكثر اعتماداً على دورة وحي/عفو عالمية تجمع تقاليد متعددة. لذلك المقارنة الأقوى مع نقطة نور تقع على مستوى البنية الجامعة لا الهوية الشخصية.", "rafi": "غير مثبت", "lux": "تقاطع بنيوي قوي", "guard": "تقاطع وظيفي", "url": "research/savior/caodai.html"}, {"id": "daesoon", "o": 11, "f": "شرق آسيا والديانات الحديثة", "t": "دايسون / جونغسان (Daesoon / Jeungsan) · حل المظالم والتجديد", "n": "Resolution of grievances / mutual beneficence", "c": "B", "conf": "عالٍ", "pop": "حركة دينية كورية حديثة", "sum": "محورها البارز حل المظالم، المنفعة المتبادلة، الانسجام وإعادة ترتيب العالم، مع لاهوت خاص بسانغجي (Sangje). المقارنة مع نقطة نور هنا أخلاقية-حضارية أكثر من كونها «هوية مخلّص».", "rafi": "غير مثبت", "lux": "تقاطع قيمي قوي", "guard": "تقاطع وظيفي متوسط", "url": "research/savior/daesoon.html"}, {"id": "sikhism", "o": 12, "f": "الديانات الهندية", "t": "السيخية · الخلاص بلا مخلّص أخروي مركزي", "n": "No central end-time savior", "c": "C", "conf": "متوسط", "pop": "ضمن فئة الديانات الأخرى عالمياً", "sum": "في المسح الأولي، السيخية لا تتمحور حول انتظار مخلّص أخروي واحد على نمط المسيح أو المهدي أو كالكي (Kalki). الخلاص يرتبط بالله، بالنام، بالنعمة والحياة الأخلاقية، مع مركزية الغورو غرانث صاحب بعد الغورو العاشر.", "rafi": "غير قابل للتطبيق", "lux": "تقاطع أخلاقي محتمل", "guard": "تقاطع خدمي فقط", "url": "research/savior/sikhism.html"}, {"id": "jainism", "o": 13, "f": "الديانات الهندية", "t": "الجاينية · التيرثانكارا (Tīrthaṅkara) لا مخلّص خالق", "n": "Tirthankara model", "c": "C", "conf": "متوسط", "pop": "ضمن فئة الديانات الأخرى عالمياً", "sum": "الجاينية تقدم نموذجاً مختلفاً جذرياً: التيرثانكارا (Tīrthaṅkara) معلمون/فاتحو معبر للتحرر، لا آلهة خالقة تنقذ العالم من الخارج. لذلك هي اختبار مهم ضد فرضية أن كل حضارة تنتظر «مخلّصاً».", "rafi": "غير قابل للتطبيق مباشرة", "lux": "تقاطع أخلاقي", "guard": "تقاطع ضعيف", "url": "research/savior/jainism.html"}, {"id": "secular-humanism", "o": 14, "f": "الفلسفات واللادينية", "t": "الإنسانية العلمانية · الخلاص كمسؤولية بشرية", "n": "Collective human agency", "c": "C", "conf": "عالٍ", "pop": "غير المنتمين دينياً 24.2% عالمياً؛ وليسوا كتلة فلسفية واحدة", "sum": "غير المنتمين دينياً ليسوا «ديناً» موحداً، والإنسانية العلمانية ليست عقيدة كل اللادينيين. لكنها نموذج مهم يقلب السؤال: لا مخلّص منتظر، بل مسؤولية بشرية ومؤسسات ونقد وأدلة.", "rafi": "غير قابل للتطبيق نبوئياً", "lux": "قابل للاختبار عملياً", "guard": "دور مدني قابل للنقد", "url": "research/savior/secular-humanism.html"}, {"id": "confucian-daoist", "o": 15, "f": "الفلسفات والتقاليد الصينية", "t": "الصين · الحكيم والوحدة الكبرى (Datong) والتيارات المهدوية", "n": "Sage / Great Unity / messianic currents", "c": "B", "conf": "منخفض–متوسط", "pop": "تقاليد واسعة يصعب عدّها ديموغرافياً كهوية واحدة", "sum": "التقاليد الصينية لا تقدم «مخلّصاً واحداً» بسيطاً. توجد صور الحاكم الحكيم والوحدة الكبرى (Datong)، وفي تاريخ الطاوية والحركات الشعبية تيارات مهدوية مثل لي هونغ (Li Hong)، لكنها ليست عقيدة موحدة لكل الكونفوشيين أو الطاويين.", "rafi": "غير مثبت", "lux": "تقاطع حضاري", "guard": "تقاطع رمزي", "url": "research/savior/confucian-daoist.html"}, {"id":"guardian-benefactor","o":16,"f":"الفلسفات واللادينية","t":"الحارس المُحسن · نموذج أخلاقي عبر التقاليد","n":"Guardian / Benefactor Archetype","c":"C","conf":"متوسط–عالٍ","pop":"عقدة مقارنة عابرة للتقاليد، وليست ديانة مستقلة","sum":"عقدة مستقلة تفصل العمل الأخلاقي والوظيفي عن ادعاء الهوية النبوئية. تقارن حماية الضعيف، الخدمة، إطعام المحتاج، حفظ المعرفة، بناء الجسور، العدل وقابلية النقد عبر تقاليد متعددة.","rafi":"اختبار سلوكي فقط","lux":"تقاطع وظيفي قابل للقياس","guard":"الدور موضوع الاختبار نفسه","url":"guardian-benefactor.html"}, {"id":"number-letter-lab","o":17,"f":"الفلسفات واللادينية","t":"مختبر الأسماء والأعداد والحروف","n":"Numerical & Letter Systems Lab","c":"C","conf":"منهجي/تجريبي","pop":"أداة مقارنة؛ ليست عقيدة مستقلة","sum":"مختبر مستقل يفصل Gematrix والجمل العربي والجيماتريا العبرية والإيزوبسيفي اليوناني والعددية الغربية الحديثة، ويحفظ صيغة الاسم وجدول القيم لكل نتيجة.","rafi":"Rafy Alhajji وRafi Alhaji بالأحرف اللاتينية؛ رافي الحجي ورافي الحاجي بالأحرف العربية","lux":"أداة بحث قابلة للتوسع","guard":"لا يثبت هوية نبوئية","url":"number-letter-lab.html"}];


